export interface Card {
  monster: string;
  rank?: number;
}

const SPHINX = "sphinx";

const isSphinx = (card: Card): boolean => card.monster === SPHINX;

// A card's type is its monster alone. Rank is a variation within a type, not a
// type of its own: Undead Warrior (1) and Undead Warrior (3) are one type.
const typeOf = (card: Card): string => card.monster;

const countMonsterTypes = (army: Card[]): number =>
  new Set(army.map(typeOf)).size;

// Points per Sphinx step up with the army's variety. Deliberately a step
// table, not a formula: the remaining examples decide the rule's true shape.
// Ordered from the most varied army down; the first tier the army reaches wins.
const POINTS_PER_SPHINX_TIERS: { minMonsterTypes: number; pointsPerSphinx: number }[] = [
  { minMonsterTypes: 6, pointsPerSphinx: 5 },
  { minMonsterTypes: 4, pointsPerSphinx: 3 },
];

const BASE_POINTS_PER_SPHINX = 2;

const pointsPerSphinxFor = (monsterTypeCount: number): number =>
  POINTS_PER_SPHINX_TIERS.find((tier) => monsterTypeCount >= tier.minMonsterTypes)
    ?.pointsPerSphinx ?? BASE_POINTS_PER_SPHINX;

const countSphinxes = (army: Card[]): number => army.filter(isSphinx).length;

export const scoreArmy = (army: Card[]): number =>
  countSphinxes(army) * pointsPerSphinxFor(countMonsterTypes(army));
=====CLI=====
import { scoreArmy, type Card } from "./sphinx-score.js";

const readStdin = async (): Promise<string> => {
  const chunks: Buffer[] = [];
  for await (const chunk of process.stdin) chunks.push(chunk as Buffer);
  return Buffer.concat(chunks).toString("utf8");
};

const main = async (): Promise<void> => {
  const { army } = JSON.parse(await readStdin()) as { army: Card[] };
  process.stdout.write(`${JSON.stringify({ score: scoreArmy(army) })}\n`);
};

await main();
=====SPEC=====
import { describe, it, expect } from "vitest";
import { scoreArmy } from "./sphinx-score.js";

describe("Sphinx scoring", () => {
  it("scores 0 for an army with no Sphinx — Chimera, Orthrus, Zombie → 0 points", () => {
    expect(
      scoreArmy([{ monster: "chimera" }, { monster: "orthrus" }, { monster: "zombie" }]),
    ).toBe(0);
  });
  it("scores a Sphinx counting itself among the types — Sphinx, Cyclops → 2 points", () => {
    expect(scoreArmy([{ monster: "sphinx" }, { monster: "cyclops" }])).toBe(2);
  });
  it("scores exactly three types as 1 point per Sphinx plus its own point — Sphinx, Chimera, Orthrus → 2 points", () => {
    expect(
      scoreArmy([{ monster: "sphinx" }, { monster: "chimera" }, { monster: "orthrus" }]),
    ).toBe(2);
  });
  it("scores four types as 2 per type beyond three — Sphinx, Chimera, Orthrus, Zombie, Hydra → 3 points", () => {
    expect(
      scoreArmy([
        { monster: "sphinx" },
        { monster: "chimera" },
        { monster: "orthrus" },
        { monster: "zombie" },
        { monster: "hydra" },
      ]),
    ).toBe(3);
  });
  it("scores five types as 2 per type beyond three — Sphinx, Chimera, Orthrus, Zombie, Hydra, Cyclops → 5 points", () => {
    expect(
      scoreArmy([
        { monster: "sphinx" },
        { monster: "chimera" },
        { monster: "orthrus" },
        { monster: "zombie" },
        { monster: "hydra" },
        { monster: "cyclops" },
      ]),
    ).toBe(5);
  });
  it("counts duplicate cards of the same monster as one type — Sphinx, Chimera, Chimera, Chimera, Orthrus, Orthrus → 2 points", () => {
    expect(
      scoreArmy([
        { monster: "sphinx" },
        { monster: "chimera" },
        { monster: "chimera" },
        { monster: "chimera" },
        { monster: "orthrus" },
        { monster: "orthrus" },
      ]),
    ).toBe(2);
  });
  it("scores each Sphinx independently and counts Sphinx as one type — Sphinx, Sphinx, Chimera, Orthrus → 4 points", () => {
    expect(
      scoreArmy([
        { monster: "sphinx" },
        { monster: "sphinx" },
        { monster: "chimera" },
        { monster: "orthrus" },
      ]),
    ).toBe(4);
  });
  it("scores each Sphinx independently beyond three types — Sphinx, Sphinx, Chimera, Orthrus, Zombie → 6 points", () => {
    expect(
      scoreArmy([
        { monster: "sphinx" },
        { monster: "sphinx" },
        { monster: "chimera" },
        { monster: "orthrus" },
        { monster: "zombie" },
      ]),
    ).toBe(6);
  });
  it("treats Undead Warrior ranks as a single type — Sphinx, Undead Warrior (1), Undead Warrior (3), Chimera → 2 points", () => {
    expect(
      scoreArmy([
        { monster: "sphinx" },
        { monster: "undead-warrior", rank: 1 },
        { monster: "undead-warrior", rank: 3 },
        { monster: "chimera" },
      ]),
    ).toBe(2);
  });
  it("treats all three Undead Warrior ranks as a single type among many — Sphinx, UW(1), UW(2), UW(3), Cyclops, Orthrus, Chimera → 3 points", () => {
    expect(
      scoreArmy([
        { monster: "sphinx" },
        { monster: "undead-warrior", rank: 1 },
        { monster: "undead-warrior", rank: 2 },
        { monster: "undead-warrior", rank: 3 },
        { monster: "cyclops" },
        { monster: "orthrus" },
        { monster: "chimera" },
      ]),
    ).toBe(3);
  });
});

